class Morsec < Formula
  desc "Local secret broker: coding agents use your secrets without seeing them"
  homepage "https://github.com/csakash/morsec"
  url "https://github.com/csakash/morsec/releases/download/v0.2.0/morsec-0.2.0-aarch64-apple-darwin.tar.gz"
  version "0.2.0"
  sha256 "f074680b6ec600debd8ad0f0b2b36094582f5910060e4902aace1b69a8de73dd"

  # Prebuilt, Developer ID signed and notarized binaries. Not built from source: the keychain
  # trusts only the signed msd (identifier cc.morsec.msd and the release team), so a local
  # build could not read the keys stored by the previous version.
  depends_on arch: :arm64
  depends_on macos: :ventura # built with MACOSX_DEPLOYMENT_TARGET=13.0

  def install
    # ms-shim (run mode) must sit next to ms: ms run --link-shims and ms doctor look for it
    # beside ms's real path, which is this Cellar bin/. The list matches packaging/macos/sign-targets.
    bin.install "bin/ms", "bin/msd", "bin/ms-shim"
    bin.install_symlink "ms" => "mors"
    (share/"morsec").install "share/morsec/BUILDINFO", "share/morsec/morsec.cdx.json"
  end

  def caveats
    <<~EOS
      Set morsec up (creates the vault and starts msd as a LaunchAgent):
        ms init
      morsec has no auto-update. Upgrade with brew upgrade morsec, then restart msd
      (or log out and back in), with your user id (id -u) as UID:
        launchctl kickstart -k gui/UID/cc.morsec.msd
    EOS
  end

  test do
    assert_match "morsec #{version}", shell_output("#{bin}/ms --version")
    assert_match "morsec #{version}", shell_output("#{bin}/mors --version")
    # Under its own name ms-shim refuses (exit 64) and says how to link it.
    assert_match "ms run --link-shims", shell_output("#{bin}/ms-shim 2>&1", 64)
  end
end
